# compabibility with older RHBZ",accepted,1,NO,False,context_required,context_required,True,0.7,The hack for backwards compatibility suggests reliance on external behavior or conventions not visible in the snippet.,Behavior of self.pre_translation() | Behavior of self.post_translation() | Details of older RHBZ compatibility requirements,0.0,0.0,0.0,pass,True,0.7398,0.9,context_required,low,function,0.8,0.8,0.2,0.499,0.8,0.7398,0.499,0.8,pass,weak_method_context,,"The SATD clearly identifies a specific hack related to backwards compatibility, and the code context supports a targeted repair.",Pass to fixer for smallest local edit.,high,high,high,high,hack to preserve backwards compatibility,need a hack to preserve backwards compatibility,False,method_context_only,,method_context,0,0,0,post_translation | _proxy.Bug.search,RHBugzilla.post_translation,_proxy.Bug.search,1,"[{""method_name"": ""RHBugzilla.post_translation"", ""path"": ""bugzilla/rhbugzilla.py"", ""class_name"": ""RHBugzilla"", ""start_line"": 427, ""end_line"": 477, ""source"": ""def post_translation(self, query, bug):
        '''Translates the query result'''
        tmpstr = []
        if 'flags' in bug:
            for tmp in bug['flags']:
                tmpstr.append(""%s%s"" % (tmp['name'], tmp['status']))

            bug['flags'] = "", "".join(tmpstr)
        if 'blocks' in bug:
            if len(bug['blocks']) > 0:
                bug['blockedby'] = ', '.join(map(str, bug['blocks']))
                bug['blocked'] = ', '.join(map(str, bug['blocks']))
            else:
                bug['blockedby'] = ''
                bug['blocked'] = ''
        if 'id' in bug:
            bug['bug_id'] = bug['id']
        if 'keywords' in bug:
            if len(bug['keywords']) > 0:
                bug['keywords'] = ', '.join(bug['keywords'])
            else:
                bug['keywords'] = ''
        if 'component' in bug:
            # we have to emulate the old behavior and add 'components' as
            # list instead
            bug['components'] = bug['component']
            bug['component'] = bug['component'][0]
        if 'alias' in bug:
            if len(bug['alias']) > 0:
                bug['alias'] = ', '.join(bug['alias'])
            else:
                bug['alias'] = ''
        if 'groups' in bug:
            # groups went to the opposite direction: it got simpler
            # instead of having name, ison, description, it's now just
            # an array of strings of the groups the bug belongs to
            # we're emulating the old behaviour here
            tmp = list()
            for g in bug['groups']:
                t = {}
                t['name'] = g
                t['description'] = g
                t['ison'] = 1
                tmp.append(t)
            bug['groups'] = tmp
        if 'summary' in bug:
            bug['short_desc'] = bug['summary']
        if 'whiteboard' in bug:
            bug['status_whiteboard'] = bug['whiteboard']
        if 'status' in bug:
            bug['bug_status'] = bug['status']"", ""found"": true, ""signature"": """", ""callsite_slice"": """", ""evidence_slice"": """", ""match_score"": 0, ""confidence"": 0.0, ""confidence_label"": """"}]",[],[],True,approved,"def _query(self, query):

